2	import { Box, Static, Text, render, useApp, useInput, useStdin, useStdout } from "ink";
3	import { COMMANDS, resolveCommand, runCommand } from "./commands.ts";
4	import { type AgentState, newAgentState, reviewGoal, runTurn } from "./core/agent.ts";
