21	type ItemKind = "banner" | "user" | "assistant" | "tool" | "notice" | "error" | "shell";
22	
23	interface Item {
24	  id: number;
25	  kind: ItemKind;
26	  text: string;
27	  tool?: string;
28	  status?: "ok" | "error";
29	  hint?: string;
30	  /** Display-only tail of an oversized item whose full copy is already in
31	   * scrollback; dropped (not re-flushed) when the next item arrives. */
32	}
33	
34	let nextId = 1;
35	
36	interface PendingApproval {
37	  request: ApprovalRequest;
38	  resolve: (ok: boolean) => void;
39	}
40	
41	interface Suggestion {
42	  name: string;
43	  description: string;
44	}
