46	function toolHint(args: Record<string, unknown>): string {
47	  for (const key of ["command", "path", "pattern", "query", "task", "name", "fact", "ids"]) {
48	    const v = args[key];
49	    if (typeof v === "string" && v) return v.length > 64 ? v.slice(0, 64) + "…" : v;
50	  }
51	  return "";
52	}
53	
54	function fmtTok(n: number): string {
55	  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
56	  if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
57	  return String(Math.round(n));
58	}
59	
60	const EFFORT_OPTIONS: Array<{ value: Effort; blurb: string }> = [
61	  { value: "low", blurb: "quick answers · 6 tool rounds" },
62	  { value: "medium", blurb: "balanced · 14 tool rounds" },
63	  { value: "high", blurb: "thorough · 28 tool rounds" },
64	  { value: "max", blurb: "exhaustive · 50 tool rounds" },
65	  { value: "ultracode", blurb: "plans · todos · parallel agents · unlimited rounds" },
66	];
67	
68	/** Tokens-per-second meter. SSE deltas carry a variable number of tokens, so
69	 * each record estimates tokens from text length (~4 chars/token) instead of
70	 * counting events. Rate averages over the last 3s — or the stream's actual age
71	 * when younger, so the first seconds aren't diluted by an empty window. Trend
72	 * compares the last 3s against the 3s before it. */
73	class TpsMeter {
74	  private stamps: Array<{ t: number; tok: number }> = [];
75	  private startedAt = 0;
76	  record(text: string): void {
77	    const now = Date.now();
78	    if (this.stamps.length === 0) this.startedAt = now;
79	    this.stamps.push({ t: now, tok: Math.max(1, Math.round(text.length / 4)) });
80	    if (this.stamps.length > 20000) this.stamps.splice(0, 10000);
81	  }
82	  reset(): void {
83	    this.stamps = [];
84	    this.startedAt = 0;
85	  }
86	  tps(): number {
87	    if (this.stamps.length === 0) return 0;
88	    const now = Date.now();
89	    let tok = 0;
90	    for (let i = this.stamps.length - 1; i >= 0 && now - this.stamps[i].t <= 3000; i--) tok += this.stamps[i].tok;
91	    const windowMs = Math.min(3000, Math.max(250, now - this.startedAt));
92	    return tok / (windowMs / 1000);
93	  }
94	  trend(): "up" | "down" {
95	    const now = Date.now();
96	    let last3 = 0;
97	    let prev3 = 0;
98	    for (let i = this.stamps.length - 1; i >= 0; i--) {
99	      const age = now - this.stamps[i].t;
100	      if (age <= 3000) last3 += this.stamps[i].tok;
101	      else if (age <= 6000) prev3 += this.stamps[i].tok;
102	      else break;
103	    }
104	    return last3 >= prev3 ? "up" : "down";
105	  }
106	}
