108	export function App({ opts }: { opts: { yolo: boolean; intro: boolean; resume?: string } }) {
109	  const { exit } = useApp();
110	  const { stdin } = useStdin();
111	  const { stdout } = useStdout();
112	  const config = loadConfig();
113	  if (opts.yolo) config.yolo = true;
114	
115	  const [termRows, setTermRows] = useState(stdout?.rows ?? 30);
116	  useEffect(() => {
117	    if (!stdout) return;
118	    const onResize = () => setTermRows(stdout.rows);
119	    stdout.on("resize", onResize);
120	    return () => {
121	      stdout.off("resize", onResize);
122	    };
123	  }, [stdout]);
124	
125	  const [phase, setPhase] = useState<"intro" | "ready">(
126	    opts.intro && config.intro ? "intro" : "ready",
127	  );
128	  const [staticItems, setStaticItems] = useState<Item[]>([]);
129	  const [liveItems, setLiveItems] = useState<Item[]>([]);
130	  const [running, setRunning] = useState(false);
131	  const [stream, setStream] = useState("");
132	  const [thoughtLines, setThoughtLines] = useState<string[]>([]);
133	  const [thoughtExpanded, setThoughtExpanded] = useState(false);
134	  const [thinking, setThinking] = useState(false);
135	  const [activeTool, setActiveTool] = useState<{ tool: string; hint: string } | null>(null);
136	  const [approval, setApproval] = useState<PendingApproval | null>(null);
137	  const [todos, setTodos] = useState<TodoItem[]>([]);
138	  const [spin, setSpin] = useState(0);
139	  const [elapsed, setElapsed] = useState(0);
140	  const [tps, setTps] = useState(0);
141	  const [tpsTrend, setTpsTrend] = useState<"up" | "down">("up");
142	  const [usage, setUsage] = useState({ prompt: 0, completion: 0, total: 0 });
143	  const [cost, setCost] = useState(0);
144	  const [ctxTokens, setCtxTokens] = useState(0);
145	  const [history, setHistory] = useState<string[]>([]);
146	  const [inputValue, setInputValue] = useState("");
147	  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
148	  const [suggestionIdx, setSuggestionIdx] = useState(0);
149	  const [effortMenu, setEffortMenu] = useState(false);
150	  const [effortMenuIdx, setEffortMenuIdx] = useState(0);
151	  const [ctrlCArmed, setCtrlCArmed] = useState(false);
152	  const [goal, setGoal] = useState("");
153	  const [goalRetries, setGoalRetries] = useState(0);
154	
155	  const stateRef = useRef<AgentState>(newAgentState());
156	  const goalRef = useRef("");
157	  const goalRetriesRef = useRef(0);
158	  const abortRef = useRef<AbortController | null>(null);
159	  const verbRef = useRef(THINKING_VERBS[Math.floor(Math.random() * THINKING_VERBS.length)]);
160	  const titleRef = useRef("");
161	  const meterRef = useRef(new TpsMeter());
162	  const reasoningBufRef = useRef("");
163	  const activeToolHintRef = useRef("");
164	  const streamBufRef = useRef("");
165	  const queueRef = useRef<string[]>([]);
166	  const submitRef = useRef<((text: string) => void) | null>(null);
167	  const rowsRef = useRef(termRows);
168	  rowsRef.current = termRows;
169	
170	  const liveRef = useRef<Item[]>([]);
171	  const staticRef = useRef<Item[]>([]);
172	
173	  // Transcript items live in the docked region (visible above the input) and
174	  // overflow into Static scrollback oldest-first, so recent output is always
175	  // on screen and full history is always in the terminal's own scrollback.
176	  const estimateRows = useCallback((item: Item): number => {
177	    if (item.kind === "banner") return 4;
178	    const cols = Math.max(40, (process.stdout.columns ?? 100) - 6);
179	    const textRows = item.text
180	      ? item.text.split("\n").reduce((a, l) => a + Math.max(1, Math.ceil(l.length / cols)), 0)
181	      : 0;
182	    if (item.kind === "tool") return 1 + textRows;
183	    return textRows + 1;
184	  }, []);
185	
186	  const liveBudget = useCallback((isRunning: boolean): number => {
187	    const r = rowsRef.current;
188	    return isRunning ? Math.max(4, Math.floor((r - 12) / 2)) : Math.max(6, r - 12);
189	  }, []);
190	
191	  const runningRef = useRef(false);
192	
193	  const push = useCallback(
194	    (item: Omit<Item, "id">) => {
195	      const next: Item = { ...item, id: nextId++ };
196	      let live = [...liveRef.current, next];
197	      const budget = liveBudget(runningRef.current);
198	      const flushed: Item[] = [];
199	      let total = live.reduce((a, it) => a + estimateRows(it), 0);
200	      while (total > budget && live.length > 1) {
201	        const old = live.shift()!;
202	        flushed.push(old);
203	        total -= estimateRows(old);
204	      }
205	      if (live.length === 1 && estimateRows(live[0]) > budget) {
206	        // An oversized item goes straight to Static scrollback. The docked
207	        // region is content-sized and sits directly below Static now, so a
208	        // duplicated "tail" copy would render the same content twice.
209	        flushed.push(live[0]);
210	        live = [];
211	      }
212	      liveRef.current = live;
213	      if (flushed.length > 0) {
214	        staticRef.current = [...staticRef.current, ...flushed];
215	        setStaticItems(staticRef.current);
216	      }
217	      setLiveItems(live);
218	    },
219	    [estimateRows, liveBudget],
220	  );
221	
222	  /** Re-trim live items to the current budget (turn start shrinks the budget
223	   * to make room for the stream/thought area). */
224	  const trimLive = useCallback(() => {
225	    let live = [...liveRef.current];
226	    const budget = liveBudget(runningRef.current);
227	    const flushed: Item[] = [];
228	    let total = live.reduce((a, it) => a + estimateRows(it), 0);
229	    while (total > budget && live.length > 0) {
230	      const old = live.shift()!;
231	      flushed.push(old);
232	      total -= estimateRows(old);
233	    }
234	    if (flushed.length > 0) {
235	      staticRef.current = [...staticRef.current, ...flushed];
236	      setStaticItems(staticRef.current);
237	    }
238	    liveRef.current = live;
239	    setLiveItems(live);
240	  }, [estimateRows, liveBudget]);
241	
242	  useEffect(() => {
243	    if (phase !== "ready") return;
244	    push({ kind: "banner", text: "" });
245	    trace("session.start", { mode: "tui" });
246	    if (opts.resume) {
247	      const loaded = loadSession(opts.resume);
248	      if (loaded) {
249	        stateRef.current.messages = loaded.messages;
250	        titleRef.current = loaded.title;
251	        push({
252	          kind: "notice",
253	          text: `resumed session ${opts.resume} — "${loaded.title}" (${loaded.messages.length} messages)`,
254	        });
255	      } else {
256	        push({ kind: "error", text: `could not load session ${opts.resume}` });
257	      }
258	    }
259	    // eslint-disable-next-line react-hooks/exhaustive-deps
260	  }, [phase]);
261	
262	  // One ticker drives spinner, elapsed, tps, AND the throttled stream flush —
263	  // streaming deltas only repaint ~8x/s instead of per-token, which kills the
264	  // layout flicker on fast generations.
265	  useEffect(() => {
266	    if (!running) return;
267	    const started = Date.now();
268	    const t = setInterval(() => {
269	      setSpin((s) => s + 1);
270	      setElapsed(Math.floor((Date.now() - started) / 1000));
271	      setTps(meterRef.current.tps());
272	      setTpsTrend(meterRef.current.trend());
273	      const visible = visiblePrefix(streamBufRef.current);
274	      // Cap by *rendered* rows: wrapped lines count as multiple rows, or the
275	      // region overflows the fixed-height frame and corrupts the redraw.
276	      const cols = Math.max(40, (process.stdout.columns ?? 100) - 6);
277	      const budget = Math.max(4, Math.floor((rowsRef.current - 12) / 2));
278	      const lines = visible.split("\n");
279	      const kept: string[] = [];
280	      let rows = 0;
281	      for (let i = lines.length - 1; i >= 0 && rows < budget; i--) {
282	        rows += Math.max(1, Math.ceil(lines[i].length / cols));
283	        kept.unshift(lines[i]);
284	      }
285	      setStream(kept.join("\n"));
286	    }, 120);
287	    return () => clearInterval(t);
288	  }, [running]);
289	
290	  // Mouse click toggles the thought dropdown while thinking is shown.
291	  useEffect(() => {
292	    const wantMouse = running && loadConfig().thoughts;
293	    if (!wantMouse || !stdin) return;
294	    process.stdout.write("\x1b[?1000h\x1b[?1006h");
295	    const onData = (data: Buffer) => {
296	      const s = data.toString("latin1");
297	      if (/\x1b\[<0;\d+;\d+M/.test(s)) setThoughtExpanded((e) => !e);
298	    };
299	    stdin.on("data", onData);
300	    return () => {
301	      stdin.off("data", onData);
302	      process.stdout.write("\x1b[?1006l\x1b[?1000l");
303	    };
304	  }, [running, stdin]);
305	
306	  useInput(
307	    (input, key) => {
308	      if (effortMenu) {
309	        if (key.upArrow) setEffortMenuIdx((i) => (i + EFFORT_OPTIONS.length - 1) % EFFORT_OPTIONS.length);
310	        else if (key.downArrow) setEffortMenuIdx((i) => (i + 1) % EFFORT_OPTIONS.length);
311	        else if (key.return) {
312	          const chosen = EFFORT_OPTIONS[effortMenuIdx].value;
313	          saveConfig({ effort: chosen });
314	          setEffortMenu(false);
315	          push({ kind: "notice", text: `effort set to ${chosen} — ${EFFORT_OPTIONS[effortMenuIdx].blurb}` });
316	        } else if (key.escape) setEffortMenu(false);
317	        return;
318	      }
319	      if (key.ctrl && input === "t") {
320	        setThoughtExpanded((e) => !e);
321	        return;
322	      }
323	      if (key.escape && running) {
324	        abortRef.current?.abort();
325	        return;
326	      }
327	      if (key.ctrl && input === "c") {
328	        if (ctrlCArmed) {
329	          saveSession(stateRef.current, titleRef.current || "untitled");
330	          trace("session.end", { mode: "tui", usage: stateRef.current.totalUsage });
331	          exit();
332	          return;
333	        }
334	        setCtrlCArmed(true);
335	        setTimeout(() => setCtrlCArmed(false), 1500);
336	      }
337	    },
338	    { isActive: phase === "ready" },
339	  );
340	
341	  const appendThought = useCallback((delta: string) => {
342	    reasoningBufRef.current += delta;
343	    let buf = reasoningBufRef.current;
344	    if (/<\/think>/i.test(buf)) setThinking(false);
345	    else if (/<think>/i.test(buf)) setThinking(true);
346	    const cleaned = buf.replace(/<\/?think>/gi, "");
347	    const lines = cleaned.split("\n").map((l) => l.trim()).filter(Boolean);
348	    setThoughtLines(lines.slice(-200));
349	  }, []);
350	
351	  const run = useCallback(
352	    async (text: string) => {
353	      setRunning(true);
354	      runningRef.current = true;
355	      let aborted = false;
356	      trimLive();
357	      setStream("");
358	      setThoughtLines([]);
359	      setThinking(false);
360	      setTodos([]);
361	      meterRef.current.reset();
362	      reasoningBufRef.current = "";
363	      streamBufRef.current = "";
364	      verbRef.current = THINKING_VERBS[Math.floor(Math.random() * THINKING_VERBS.length)];
365	      const abort = new AbortController();
366	      abortRef.current = abort;
367	      try {
368	        await runTurn(
369	          stateRef.current,
370	          text,
371	          loadConfig().effort,
372	          {
373	            onDelta: (d, channel) => {
374	              meterRef.current.record(d);
375	              if (channel === "content") {
376	                streamBufRef.current += d;
377	              } else {
378	                appendThought(d);
379	              }
380	            },
381	            onAssistantText: (t) => {
382	              push({ kind: "assistant", text: t });
383	              streamBufRef.current = "";
384	              setStream("");
385	            },
386	            onToolStart: (tool, args) => {
387	              streamBufRef.current = "";
388	              setStream("");
389	              reasoningBufRef.current = "";
390	              setThoughtLines([]);
391	              const hint = toolHint(args);
392	              activeToolHintRef.current = hint;
393	              setActiveTool({ tool, hint });
394	            },
395	            onToolEnd: (tool, status, output) => {
396	              setActiveTool(null);
397	              const preview =
398	                tool === "bash" || tool === "grep" || tool === "web_search" || tool === "subagent" || tool === "await_agents"
399	                  ? output.split("\n").slice(0, 3).join("\n").slice(0, 240)
400	                  : output.split("\n")[0]?.slice(0, 120) ?? "";
401	              push({ kind: "tool", text: preview, tool, status, hint: activeToolHintRef.current });
402	            },
403	            onApproval: (request) =>
404	              new Promise<boolean>((resolve) => setApproval({ request, resolve })),
405	            onUsage: (u, c) => {
406	              setUsage((prev) => ({
407	                prompt: prev.prompt + u.prompt_tokens,
408	                completion: prev.completion + u.completion_tokens,
409	                total: prev.total + u.total_tokens,
410	              }));
411	              setCost((prev) => prev + c);
412	              setCtxTokens(u.prompt_tokens);
413	            },
414	            onNotice: (t) => push({ kind: "notice", text: t }),
415	            onTodos: (t) => setTodos(t),
416	          },
417	          abort.signal,
418	        );
419	      } catch (err) {
420	        const msg = err instanceof Error ? err.message : String(err);
421	        if (msg === "aborted" || abort.signal.aborted) {
422	          aborted = true;
423	          push({ kind: "notice", text: "interrupted — context kept, carry on when ready" });
424	        } else {
425	          push({ kind: "error", text: msg });
426	          logger.error("tui.turn_error", msg);
427	        }
428	      } finally {
429	        setRunning(false);
430	        runningRef.current = false;
431	        setActiveTool(null);
432	        setApproval(null);
433	        setStream("");
434	        streamBufRef.current = "";
435	        setThinking(false);
436	        if (!titleRef.current) titleRef.current = text.slice(0, 60);
437	        saveSession(stateRef.current, titleRef.current);
438	        if (stateRef.current.lastPromptTokens > AUTO_COMPACT_THRESHOLD) {
439	          push({ kind: "notice", text: "context is getting heavy — auto-compacting…" });
440	          try {
441	            const result = await compactHistory(stateRef.current);
442	            push({ kind: "notice", text: result });
443	          } catch {
444	            push({ kind: "notice", text: "auto-compact failed; /compact to retry" });
445	          }
446	        }
447	
448	        // Goal reviewer: if a goal was set, check whether it was achieved.
449	        // Skip if the turn was aborted. Retries indefinitely until the goal is met.
450	        const currentGoal = goalRef.current;
451	        if (!aborted && currentGoal && stateRef.current.messages.length > 1) {
452	          push({ kind: "notice", text: "goal reviewer checking if the goal was met…" });
453	          try {
454	            const verdict = await reviewGoal(stateRef.current, currentGoal);
455	            if (verdict.done) {
456	              push({ kind: "notice", text: `✓ goal met: ${verdict.reason}` });
457	              goalRef.current = "";
458	              setGoal("");
459	              goalRetriesRef.current = 0;
460	              setGoalRetries(0);
461	            } else {
462	              goalRetriesRef.current++;
463	              setGoalRetries(goalRetriesRef.current);
464	              push({ kind: "notice", text: `✗ goal NOT met: ${verdict.reason}` });
465	              push({ kind: "notice", text: `re-prompting (attempt ${goalRetriesRef.current})…` });
466	              const rePrompt = `[goal reviewer feedback] The previous attempt did not fully achieve the goal. Reason: ${verdict.reason}\n\nOriginal goal: ${currentGoal}\n\nPlease continue working. Fix any issues, complete unfinished parts, and verify your work.`;
467	              queueRef.current.unshift(rePrompt);
468	            }
469	          } catch {
470	            push({ kind: "notice", text: "goal reviewer error — goal kept for next turn" });
471	          }
472	        }
473	
474	        const queued = queueRef.current.shift();
475	        if (queued) setTimeout(() => submitRef.current?.(queued), 30);
476	      }
477	    },
478	    [push, appendThought, trimLive],
479	  );
480	
481	  const computeSuggestions = useCallback((value: string): Suggestion[] => {
482	    if (!value.startsWith("/") || value.includes(" ")) return [];
483	    const prefix = value.slice(1).toLowerCase();
484	    const cmds = COMMANDS.filter((c) => c.name.startsWith(prefix)).map((c) => ({
485	      name: c.name,
486	      description: c.description,
487	    }));
488	    const skills = listSkills()
489	      .filter((s) => s.name.startsWith(prefix))
490	      .map((s) => ({ name: s.name, description: `skill — ${s.description}` }));
491	    return [...cmds, ...skills].slice(0, 8);
492	  }, []);
493	
494	  const onInputChange = useCallback(
495	    (value: string) => {
496	      setInputValue(value);
497	      const next = computeSuggestions(value);
498	      setSuggestions(next);
499	      setSuggestionIdx((i) => Math.min(i, Math.max(0, next.length - 1)));
500	    },
501	    [computeSuggestions],
502	  );
503	
504	  const submit = useCallback(
505	    (text: string) => {
506	      setHistory((h) => [...h.filter((x) => x !== text), text].slice(-100));
507	      setInputValue("");
508	      setSuggestions([]);
509	
510	      // Mid-run input queues instead of interleaving with the active turn.
511	      if (running) {
512	        queueRef.current.push(text);
513	        push({ kind: "notice", text: `queued — sends when this turn finishes: ${text.slice(0, 80)}` });
514	        return;
515	      }
516	
517	      if (text.startsWith("!")) {
518	        const cmd = text.slice(1).trim();
519	        push({ kind: "user", text });
520	        const proc = Bun.spawnSync(["bash", "-c", cmd], { cwd: process.cwd() });
521	        const out = (proc.stdout.toString() + proc.stderr.toString()).trim() || "(no output)";
522	        push({ kind: "shell", text: out.slice(0, 4000), hint: cmd, status: proc.exitCode === 0 ? "ok" : "error" });
523	        stateRef.current.messages.push({
524	          role: "user",
525	          content: `[I ran a shell command myself]\n$ ${cmd}\n${out.slice(0, 2000)}`,
526	        });
527	        trace("shell.passthrough", { cmd, exit: proc.exitCode });
528	        return;
529	      }
530	
531	      if (text.startsWith("/")) {
532	        const rawName = text.slice(1).split(/\s+/)[0];
533	        const resolved = resolveCommand(rawName);
534	        const skill = resolved ? null : loadSkill(rawName);
535	        if (skill) {
536	          const args = text.slice(1 + rawName.length).trim();
537	          push({ kind: "user", text });
538	          push({ kind: "notice", text: `skill /${skill.name}` });
539	          void run(expandSkill(skill, args));
540	          return;
541	        }
542	        push({ kind: "user", text });
543	        if (!resolved) {
544	          const near = COMMANDS.filter((c) => c.name.startsWith(rawName)).map((c) => `/${c.name}`);
545	          push({
546	            kind: "assistant",
547	            text:
548	              near.length > 0
