#!/usr/bin/env bun
import { VERSION, ensureDirs, loadConfig } from "./core/config.ts";
import { logger } from "./core/logger.ts";

const args = process.argv.slice(2);

function flag(name: string): boolean {
  return args.includes(name);
}

ensureDirs();
loadConfig();

if (flag("--version") || flag("-v")) {
  console.log(`glint ${VERSION}`);
  process.exit(0);
}

if (flag("--help") || flag("-h")) {
  console.log(`glint ${VERSION} — a tiny agent that punches above its weight (Glint Research)

usage:
  glint                 start the interactive TUI
  glint -p "task"       one-shot headless mode (prints result, exits)
  glint --yolo          auto-approve all tool actions
  glint --no-intro      skip the startup animation
  glint --resume <id>   resume a saved session

data: ~/.glint  (logs, diagnostics, sessions, skills, memory)`);
  process.exit(0);
}

const pIndex = args.indexOf("-p");
if (pIndex !== -1) {
  const prompt = args[pIndex + 1];
  if (!prompt) {
    console.error("error: -p requires a prompt argument");
    process.exit(1);
  }
  const { runHeadless } = await import("./headless.ts");
  await runHeadless(prompt, flag("--yolo"));
  process.exit(0);
}

if (!process.stdout.isTTY) {
  console.error("glint: interactive mode needs a TTY (use -p \"task\" for headless mode)");
  process.exit(1);
}

logger.info("app.start", { version: VERSION, cwd: process.cwd() });
const { startApp } = await import("./tui.tsx");
const resumeIndex = args.indexOf("--resume");
await startApp({
  yolo: flag("--yolo"),
  intro: !flag("--no-intro"),
  resume: resumeIndex !== -1 ? args[resumeIndex + 1] : undefined,
});

