import React, { useCallback, useEffect, useRef, useState } from "react";
import { Box, Spacer, Text, render, useApp, useInput, useStdin, useStdout } from "ink";
import { COMMANDS, resolveCommand, runCommand } from "./commands.ts";
import { type AgentState, newAgentState, reviewGoal, runTurn } from "./core/agent.ts";
import { chat } from "./core/groq.ts";
import { AUTO_COMPACT_THRESHOLD, compactHistory } from "./core/compact.ts";
import { EFFORT_LEVELS, VERSION, type Effort, effectiveModels, loadConfig, saveConfig } from "./core/config.ts";
import { SESSION_ID, trace } from "./core/diagnostics.ts";
import { logger } from "./core/logger.ts";
import { formatCost } from "./core/pricing.ts";
import { visiblePrefix } from "./core/protocol.ts";
import { loadSession, saveSession } from "./core/session.ts";
import { expandSkill, listSkills, loadSkill } from "./core/skills.ts";
import type { ApprovalRequest, TodoItem } from "./core/tools.ts";
import { Approval } from "./components/Approval.tsx";
import { Input } from "./components/Input.tsx";
import { Intro } from "./components/Intro.tsx";
import { Markdown } from "./components/Markdown.tsx";
import { SPINNER_FRAMES, THINKING_VERBS, theme } from "./theme.ts";

type ItemKind = "banner" | "user" | "assistant" | "tool" | "notice" | "error" | "shell";

interface Item {
  id: number;
  kind: ItemKind;
  text: string;
  tool?: string;
  status?: "ok" | "error";
  hint?: string;
}

let nextId = 1;

interface PendingApproval {
  request: ApprovalRequest;
  resolve: (ok: boolean) => void;
}

interface Suggestion {
  name: string;
  description: string;
}

function toolHint(args: Record<string, unknown>): string {
  for (const key of ["command", "path", "pattern", "query", "task", "name", "fact", "ids"]) {
    const v = args[key];
    if (typeof v === "string" && v) return v.length > 64 ? v.slice(0, 64) + "…" : v;
  }
  return "";
}

function fmtTok(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
  return String(Math.round(n));
}

const EFFORT_OPTIONS: Array<{ value: Effort; blurb: string }> = [
  { value: "low", blurb: "quick answers · 6 tool rounds" },
  { value: "medium", blurb: "balanced · 14 tool rounds" },
  { value: "high", blurb: "thorough · 28 tool rounds" },
  { value: "max", blurb: "exhaustive · 50 tool rounds" },
  { value: "ultracode", blurb: "plans · todos · parallel agents · unlimited rounds" },
];

/** Tokens-per-second meter. SSE deltas carry a variable number of tokens, so
 * each record estimates tokens from text length (~4 chars/token) instead of
 * counting events. Rate averages over the last 3s — or the stream's actual age
 * when younger, so the first seconds aren't diluted by an empty window. Trend
 * compares the last 3s against the 3s before it. */
class TpsMeter {
  private stamps: Array<{ t: number; tok: number }> = [];
  private startedAt = 0;
  record(text: string): void {
    const now = Date.now();
    if (this.stamps.length === 0) this.startedAt = now;
    this.stamps.push({ t: now, tok: Math.max(1, Math.round(text.length / 4)) });
    if (this.stamps.length > 20000) this.stamps.splice(0, 10000);
  }
  reset(): void {
    this.stamps = [];
    this.startedAt = 0;
  }
  tps(): number {
    if (this.stamps.length === 0) return 0;
    const now = Date.now();
    let tok = 0;
    for (let i = this.stamps.length - 1; i >= 0 && now - this.stamps[i].t <= 3000; i--) tok += this.stamps[i].tok;
    const windowMs = Math.min(3000, Math.max(250, now - this.startedAt));
    return tok / (windowMs / 1000);
  }
  trend(): "up" | "down" {
    const now = Date.now();
    let last3 = 0;
    let prev3 = 0;
    for (let i = this.stamps.length - 1; i >= 0; i--) {
      const age = now - this.stamps[i].t;
      if (age <= 3000) last3 += this.stamps[i].tok;
      else if (age <= 6000) prev3 += this.stamps[i].tok;
      else break;
    }
    return last3 >= prev3 ? "up" : "down";
  }
}

export function App({ opts }: { opts: { yolo: boolean; intro: boolean; resume?: string } }) {
  const { exit } = useApp();
  const { stdin } = useStdin();
  const { stdout } = useStdout();
  const config = loadConfig();
  if (opts.yolo) config.yolo = true;

  const [termRows, setTermRows] = useState(stdout?.rows ?? 30);
  const [termCols, setTermCols] = useState(stdout?.columns ?? 100);
  useEffect(() => {
    if (!stdout) return;
    const onResize = () => {
      setTermRows(stdout.rows);
      setTermCols(stdout.columns);
    };
    stdout.on("resize", onResize);
    return () => {
      stdout.off("resize", onResize);
    };
  }, [stdout]);

  const [phase, setPhase] = useState<"intro" | "ready">(
    opts.intro && config.intro ? "intro" : "ready",
  );
  const [items, setItems] = useState<Item[]>([]);
  // How many items to hide off the *bottom* of the transcript, i.e. how far the
  // user has scrolled up into history. 0 = following the newest output.
  const [scrollOffset, setScrollOffset] = useState(0);
  const [running, setRunning] = useState(false);
  const [stream, setStream] = useState("");
  const [thoughtLines, setThoughtLines] = useState<string[]>([]);
  const [thoughtExpanded, setThoughtExpanded] = useState(false);
  const [thinking, setThinking] = useState(false);
  const [activeTool, setActiveTool] = useState<{ tool: string; hint: string } | null>(null);
  const [approval, setApproval] = useState<PendingApproval | null>(null);
  const [todos, setTodos] = useState<TodoItem[]>([]);
  const [spin, setSpin] = useState(0);
  const [elapsed, setElapsed] = useState(0);
  const [tps, setTps] = useState(0);
  const [tpsTrend, setTpsTrend] = useState<"up" | "down">("up");
  const [usage, setUsage] = useState({ prompt: 0, completion: 0, total: 0 });
  const [cost, setCost] = useState(0);
  const [ctxTokens, setCtxTokens] = useState(0);
  const [history, setHistory] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState("");
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [suggestionIdx, setSuggestionIdx] = useState(0);
  const [effortMenu, setEffortMenu] = useState(false);
  const [effortMenuIdx, setEffortMenuIdx] = useState(0);
  const [ctrlCArmed, setCtrlCArmed] = useState(false);
  const [goal, setGoal] = useState("");
  const [goalRetries, setGoalRetries] = useState(0);

  const stateRef = useRef<AgentState>(newAgentState());
  const goalRef = useRef("");
  const goalRetriesRef = useRef(0);
  const abortRef = useRef<AbortController | null>(null);
  const verbRef = useRef(THINKING_VERBS[Math.floor(Math.random() * THINKING_VERBS.length)]);
  const titleRef = useRef("");
  const meterRef = useRef(new TpsMeter());
  const reasoningBufRef = useRef("");
  const activeToolHintRef = useRef("");
  const streamBufRef = useRef("");
  const queueRef = useRef<string[]>([]);
  const submitRef = useRef<((text: string) => void) | null>(null);
  const rowsRef = useRef(termRows);
  rowsRef.current = termRows;

  const itemsRef = useRef<Item[]>([]);

  // Fullscreen (alternate-screen) layout: the whole UI is a fixed-height frame
  // pinned to the terminal. The transcript fills the space above the footer and
  // is bottom-anchored, so the newest output always hugs the input bar and the
  // input + status line stay welded to the bottom of the screen. Old transcript
  // that doesn't fit is clipped (not lost — PgUp/PgDn scrolls back through it).
  const push = useCallback((item: Omit<Item, "id">) => {
    const next: Item = { ...item, id: nextId++ };
    itemsRef.current = [...itemsRef.current, next];
    setItems(itemsRef.current);
    // Any new output snaps the view back to the bottom (follow mode).
    setScrollOffset(0);
  }, []);

  useEffect(() => {
    if (phase !== "ready") return;
    push({ kind: "banner", text: "" });
    trace("session.start", { mode: "tui" });
    if (opts.resume) {
      const loaded = loadSession(opts.resume);
      if (loaded) {
        stateRef.current.messages = loaded.messages;
        titleRef.current = loaded.title;
        push({
          kind: "notice",
          text: `resumed session ${opts.resume} — "${loaded.title}" (${loaded.messages.length} messages)`,
        });
      } else {
        push({ kind: "error", text: `could not load session ${opts.resume}` });
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase]);

  // One ticker drives spinner, elapsed, tps, AND the throttled stream flush —
  // streaming deltas only repaint ~8x/s instead of per-token, which kills the
  // layout flicker on fast generations.
  useEffect(() => {
    if (!running) return;
    const started = Date.now();
    const t = setInterval(() => {
      setSpin((s) => s + 1);
      setElapsed(Math.floor((Date.now() - started) / 1000));
      setTps(meterRef.current.tps());
      setTpsTrend(meterRef.current.trend());
      const visible = visiblePrefix(streamBufRef.current);
      // Cap by *rendered* rows so the live stream never crowds out the footer:
      // wrapped lines count as multiple rows. Keep the tail (newest) only.
      const cols = Math.max(40, termCols - 6);
      const budget = Math.max(4, Math.floor((rowsRef.current - 12) / 2));
      const lines = visible.split("\n");
      const kept: string[] = [];
      let rows = 0;
      for (let i = lines.length - 1; i >= 0 && rows < budget; i--) {
        rows += Math.max(1, Math.ceil(lines[i].length / cols));
        kept.unshift(lines[i]);
      }
      setStream(kept.join("\n"));
    }, 120);
    return () => clearInterval(t);
  }, [running, termCols]);

  // Mouse click toggles the thought dropdown while thinking is shown.
  useEffect(() => {
    const wantMouse = running && loadConfig().thoughts;
    if (!wantMouse || !stdin) return;
    process.stdout.write("\x1b[?1000h\x1b[?1006h");
    const onData = (data: Buffer) => {
      const s = data.toString("latin1");
      if (/\x1b\[<0;\d+;\d+M/.test(s)) setThoughtExpanded((e) => !e);
    };
    stdin.on("data", onData);
    return () => {
      stdin.off("data", onData);
      process.stdout.write("\x1b[?1006l\x1b[?1000l");
    };
  }, [running, stdin]);

  useInput(
    (input, key) => {
      if (effortMenu) {
        if (key.upArrow) setEffortMenuIdx((i) => (i + EFFORT_OPTIONS.length - 1) % EFFORT_OPTIONS.length);
        else if (key.downArrow) setEffortMenuIdx((i) => (i + 1) % EFFORT_OPTIONS.length);
        else if (key.return) {
          const chosen = EFFORT_OPTIONS[effortMenuIdx].value;
          saveConfig({ effort: chosen });
          setEffortMenu(false);
          push({ kind: "notice", text: `effort set to ${chosen} — ${EFFORT_OPTIONS[effortMenuIdx].blurb}` });
        } else if (key.escape) setEffortMenu(false);
        return;
      }
      // Scroll the transcript back through history. A page is most of the
      // visible transcript height; clamp so you can't scroll past the top.
      if (key.pageUp || (key.ctrl && input === "b")) {
        const page = Math.max(1, rowsRef.current - 8);
        setScrollOffset((o) => Math.min(itemsRef.current.length - 1, o + page));
        return;
      }
      if (key.pageDown || (key.ctrl && input === "f")) {
        const page = Math.max(1, rowsRef.current - 8);
        setScrollOffset((o) => Math.max(0, o - page));
        return;
      }
      if (key.ctrl && input === "t") {
        setThoughtExpanded((e) => !e);
        return;
      }
      if (key.escape && running) {
        abortRef.current?.abort();
        return;
      }
      if (key.ctrl && input === "c") {
        if (ctrlCArmed) {
          saveSession(stateRef.current, titleRef.current || "untitled");
          trace("session.end", { mode: "tui", usage: stateRef.current.totalUsage });
          exit();
          return;
        }
        setCtrlCArmed(true);
        setTimeout(() => setCtrlCArmed(false), 1500);
      }
    },
    { isActive: phase === "ready" },
  );

  const appendThought = useCallback((delta: string) => {
    reasoningBufRef.current += delta;
    let buf = reasoningBufRef.current;
    if (/<\/think>/i.test(buf)) setThinking(false);
    else if (/<think>/i.test(buf)) setThinking(true);
    const cleaned = buf.replace(/<\/?think>/gi, "");
    const lines = cleaned.split("\n").map((l) => l.trim()).filter(Boolean);
    setThoughtLines(lines.slice(-200));
  }, []);

  const run = useCallback(
    async (text: string) => {
      setRunning(true);
      let aborted = false;
      setStream("");
      setThoughtLines([]);
      setThinking(false);
      setTodos([]);
      meterRef.current.reset();
      reasoningBufRef.current = "";
      streamBufRef.current = "";
      verbRef.current = THINKING_VERBS[Math.floor(Math.random() * THINKING_VERBS.length)];
      const abort = new AbortController();
      abortRef.current = abort;
      try {
        await runTurn(
          stateRef.current,
          text,
          loadConfig().effort,
          {
            onDelta: (d, channel) => {
              meterRef.current.record(d);
              if (channel === "content") {
                streamBufRef.current += d;
              } else {
                appendThought(d);
              }
            },
            onAssistantText: (t) => {
              push({ kind: "assistant", text: t });
              streamBufRef.current = "";
              setStream("");
            },
            onToolStart: (tool, args) => {
              streamBufRef.current = "";
              setStream("");
              reasoningBufRef.current = "";
              setThoughtLines([]);
              const hint = toolHint(args);
              activeToolHintRef.current = hint;
              setActiveTool({ tool, hint });
            },
            onToolEnd: (tool, status, output) => {
              setActiveTool(null);
              const preview =
                tool === "bash" || tool === "grep" || tool === "web_search" || tool === "subagent" || tool === "await_agents"
                  ? output.split("\n").slice(0, 3).join("\n").slice(0, 240)
                  : output.split("\n")[0]?.slice(0, 120) ?? "";
              push({ kind: "tool", text: preview, tool, status, hint: activeToolHintRef.current });
            },
            onApproval: (request) =>
              new Promise<boolean>((resolve) => setApproval({ request, resolve })),
            onUsage: (u, c) => {
              setUsage((prev) => ({
                prompt: prev.prompt + u.prompt_tokens,
                completion: prev.completion + u.completion_tokens,
                total: prev.total + u.total_tokens,
              }));
              setCost((prev) => prev + c);
              setCtxTokens(u.prompt_tokens);
            },
            onNotice: (t) => push({ kind: "notice", text: t }),
            onTodos: (t) => setTodos(t),
          },
          abort.signal,
        );
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        if (msg === "aborted" || abort.signal.aborted) {
          aborted = true;
          push({ kind: "notice", text: "interrupted — context kept, carry on when ready" });
        } else {
          push({ kind: "error", text: msg });
          logger.error("tui.turn_error", msg);
        }
      } finally {
        setRunning(false);
        setActiveTool(null);
        setApproval(null);
        setStream("");
        streamBufRef.current = "";
        setThinking(false);
        if (!titleRef.current) titleRef.current = text.slice(0, 60);
        saveSession(stateRef.current, titleRef.current);
        if (stateRef.current.lastPromptTokens > AUTO_COMPACT_THRESHOLD) {
          push({ kind: "notice", text: "context is getting heavy — auto-compacting…" });
          try {
            const result = await compactHistory(stateRef.current);
            push({ kind: "notice", text: result });
          } catch {
            push({ kind: "notice", text: "auto-compact failed; /compact to retry" });
          }
        }

        // Goal reviewer: if a goal was set, check whether it was achieved.
        // Skip if the turn was aborted. Retries indefinitely until the goal is met.
        const currentGoal = goalRef.current;
        if (!aborted && currentGoal && stateRef.current.messages.length > 1) {
          push({ kind: "notice", text: "goal reviewer checking if the goal was met…" });
          try {
            const verdict = await reviewGoal(stateRef.current, currentGoal);
            if (verdict.done) {
              push({ kind: "notice", text: `✓ goal met: ${verdict.reason}` });
              goalRef.current = "";
              setGoal("");
              goalRetriesRef.current = 0;
              setGoalRetries(0);
            } else {
              goalRetriesRef.current++;
              setGoalRetries(goalRetriesRef.current);
              push({ kind: "notice", text: `✗ goal NOT met: ${verdict.reason}` });
              push({ kind: "notice", text: `re-prompting (attempt ${goalRetriesRef.current})…` });
              const rePrompt = `[goal reviewer feedback] The previous attempt did not fully achieve the goal. Reason: ${verdict.reason}\n\nOriginal goal: ${currentGoal}\n\nPlease continue working. Fix any issues, complete unfinished parts, and verify your work.`;
              queueRef.current.unshift(rePrompt);
            }
          } catch {
            push({ kind: "notice", text: "goal reviewer error — goal kept for next turn" });
          }
        }

        const queued = queueRef.current.shift();
        if (queued) setTimeout(() => submitRef.current?.(queued), 30);
      }
    },
    [push, appendThought],
  );

  const computeSuggestions = useCallback((value: string): Suggestion[] => {
    if (!value.startsWith("/") || value.includes(" ")) return [];
    const prefix = value.slice(1).toLowerCase();
    const cmds = COMMANDS.filter((c) => c.name.startsWith(prefix)).map((c) => ({
      name: c.name,
      description: c.description,
    }));
    const skills = listSkills()
      .filter((s) => s.name.startsWith(prefix))
      .map((s) => ({ name: s.name, description: `skill — ${s.description}` }));
    return [...cmds, ...skills].slice(0, 8);
  }, []);

  const onInputChange = useCallback(
    (value: string) => {
      setInputValue(value);
      const next = computeSuggestions(value);
      setSuggestions(next);
      setSuggestionIdx((i) => Math.min(i, Math.max(0, next.length - 1)));
    },
    [computeSuggestions],
  );

  const submit = useCallback(
    (text: string) => {
      setHistory((h) => [...h.filter((x) => x !== text), text].slice(-100));
      setInputValue("");
      setSuggestions([]);

      // Mid-run input queues instead of interleaving with the active turn.
      if (running) {
        queueRef.current.push(text);
        push({ kind: "notice", text: `queued — sends when this turn finishes: ${text.slice(0, 80)}` });
        return;
      }

      if (text.startsWith("!")) {
        const cmd = text.slice(1).trim();
        push({ kind: "user", text });
        const proc = Bun.spawnSync(["bash", "-c", cmd], { cwd: process.cwd() });
        const out = (proc.stdout.toString() + proc.stderr.toString()).trim() || "(no output)";
        push({ kind: "shell", text: out.slice(0, 4000), hint: cmd, status: proc.exitCode === 0 ? "ok" : "error" });
        stateRef.current.messages.push({
          role: "user",
          content: `[I ran a shell command myself]\n$ ${cmd}\n${out.slice(0, 2000)}`,
        });
        trace("shell.passthrough", { cmd, exit: proc.exitCode });
        return;
      }

      if (text.startsWith("/")) {
        const rawName = text.slice(1).split(/\s+/)[0];
        const resolved = resolveCommand(rawName);
        const skill = resolved ? null : loadSkill(rawName);
        if (skill) {
          const args = text.slice(1 + rawName.length).trim();
          push({ kind: "user", text });
          push({ kind: "notice", text: `skill /${skill.name}` });
          void run(expandSkill(skill, args));
          return;
        }
        push({ kind: "user", text });
        if (!resolved) {
          const near = COMMANDS.filter((c) => c.name.startsWith(rawName)).map((c) => `/${c.name}`);
          push({
            kind: "assistant",
            text:
              near.length > 0
                ? `ambiguous: did you mean ${near.join(" or ")}?`
                : `unknown command: /${rawName} — try /help`,
          });
          return;
        }
        const canonical = `/${resolved}${text.slice(1 + rawName.length)}`;
        const result = runCommand(canonical, { usage, ctxTokens, cost });
        switch (result.kind) {
          case "text":
            push({ kind: "assistant", text: result.text! });
            return;
          case "effort-menu":
            setEffortMenuIdx(EFFORT_OPTIONS.findIndex((o) => o.value === loadConfig().effort));
            setEffortMenu(true);
            return;
          case "clear":
            stateRef.current = newAgentState();
            titleRef.current = "";
            setUsage({ prompt: 0, completion: 0, total: 0 });
            setCost(0);
            setCtxTokens(0);
            setTodos([]);
            goalRef.current = "";
            setGoal("");
            goalRetriesRef.current = 0;
            setGoalRetries(0);
            itemsRef.current = [];
            setItems([]);
            setScrollOffset(0);
            push({ kind: "banner", text: "" });
            return;
          case "quit":
            saveSession(stateRef.current, titleRef.current || "untitled");
            trace("session.end", { mode: "tui", usage: stateRef.current.totalUsage });
            exit();
            return;
          case "intro":
            setPhase("intro");
            return;
          case "compact":
            setRunning(true);
            void compactHistory(stateRef.current)
              .then((msg) => push({ kind: "notice", text: msg }))
              .catch((e) => push({ kind: "error", text: String(e) }))
              .finally(() => setRunning(false));
            return;
          case "resume": {
            const loaded = loadSession(result.resumeId!);
            if (loaded) {
              stateRef.current = newAgentState();
              stateRef.current.messages = loaded.messages;
              titleRef.current = loaded.title;
              push({ kind: "notice", text: `resumed "${loaded.title}" (${loaded.messages.length} messages)` });
            } else {
              push({ kind: "error", text: `no session ${result.resumeId} — see /sessions` });
            }
            return;
          }
          case "submit":
            void run(result.text!);
            return;
          case "goal-set":
            goalRef.current = result.goal!;
            setGoal(result.goal!);
            push({ kind: "notice", text: `goal set: ${result.goal!.slice(0, 100)}` });
            return;
          case "goal-clear":
            goalRef.current = "";
            setGoal("");
            push({ kind: "notice", text: "goal cleared" });
            return;
        }
      }

      // Auto-goal on high+ effort: generate a concise goal from the prompt.
      // Only auto-set if no goal is currently set (manual /goal takes precedence).
      // Obvious small talk is filtered locally — no goal, no classifier call —
      // so a "hi" never spins up the goal reviewer.
      const currentEffort = loadConfig().effort;
      const autoGoalEfforts: Effort[] = ["high", "max", "ultracode"];
      const casual =
        text.trim().length <= 40 &&
        /^(hi+|hiya|hey+|hello+|yo|sup|howdy|good\s+(morning|afternoon|evening|night)|how('s| is| are)?\s*(it going|you|things)?|what'?s up|thanks?(\s+you)?|thank you|ty|ok(ay)?|cool|nice|great|lol|haha|bye+|good\s*bye|see ya|cya)[\s!.,?~]*$/i.test(
          text.trim(),
        );
      if (autoGoalEfforts.includes(currentEffort) && !text.startsWith("!") && !goalRef.current && !casual) {
        // Set placeholder immediately so the indicator shows, then refine async.
        goalRef.current = text;
        setGoal(text);
        goalRetriesRef.current = 0;
        setGoalRetries(0);
        // Reword via a quick model call. Output NOGOAL for casual chat.
        chat(
          [
            { role: "system", content: "Analyze the user's request. If it's purely casual conversation (greetings, small talk, chit-chat, asking what you can do without a specific task) and does NOT ask for any concrete action, code change, file creation, analysis, or deliverable — output exactly NOGOAL. Otherwise, rewrite the request into a concise, actionable goal (one sentence, max 120 chars). Output only NOGOAL or the goal text." },
            { role: "user", content: text.slice(0, 1000) },
          ],
          { model: "llama-3.1-8b-instant", maxTokens: 160, temperature: 0 },
        )
          .then((res) => {
            const refined = res.content.trim().replace(/^\*{0,2}goal:?\*{0,2}\s*/i, "");
            if (!refined || refined === "NOGOAL" || refined.length < 3) {
              // Casual chat — no goal needed.
              goalRef.current = "";
              setGoal("");
            } else {
              goalRef.current = refined.slice(0, 160);
              setGoal(refined.slice(0, 160));
              push({ kind: "notice", text: `auto-goal set (${currentEffort} effort): ${refined.slice(0, 120)}` });
            }
          })
          .catch(() => {
            // On error, keep the raw prompt as goal (fail-open).
            push({ kind: "notice", text: `auto-goal set (${currentEffort} effort): ${text.slice(0, 120)} (refine failed — using your prompt verbatim)` });
          });
      }

      push({ kind: "user", text });
      void run(text);
    },
    [push, run, usage, ctxTokens, cost, exit, running],
  );
  submitRef.current = submit;

  if (phase === "intro") {
    return <Intro onDone={() => setPhase("ready")} />;
  }

  const cfg = loadConfig();
  const thoughtsOn = cfg.thoughts;
  const lastThought = thoughtLines.length > 0 ? thoughtLines[thoughtLines.length - 1] : "";
  const tpsLabel = `${tpsTrend === "up" ? "↑" : "↓"} ${fmtTok(tps)} tps`;

  // Transcript is bottom-anchored: a Spacer above the items pushes them to the
  // bottom of the (flex-grow) region, and overflow:hidden clips whatever spills
  // off the top. scrollOffset hides items off the bottom so PgUp reveals older
  // history. Clamp the offset to the list so it can never strand the view.
  const clampedOffset = Math.min(scrollOffset, Math.max(0, items.length - 1));
  const visibleItems = clampedOffset > 0 ? items.slice(0, items.length - clampedOffset) : items;

  return (
    <Box flexDirection="column" width={termCols} height={termRows}>
      {/* Transcript — fills all space above the footer, newest hugging the
          bottom. Clipped at the top; PgUp/PgDn scrolls. */}
      <Box flexGrow={1} flexDirection="column" overflow="hidden">
        <Spacer />
        {visibleItems.map((item) => (
          <ItemView key={item.id} item={item} />
        ))}
      </Box>

      {/* Live region: streaming answer + thought dropdown, just above the
          footer. flexShrink:0 keeps it from being squeezed out. */}
      {running && thoughtsOn && thoughtLines.length > 0 && (
        <Box flexShrink={0} flexDirection="column" borderStyle="round" borderColor={theme.faint} paddingX={1}>
          <Text color={theme.dim}>
            {thoughtExpanded ? "▾" : "▸"} thinking{" "}
            <Text color={theme.faint}>(click or ctrl+t to {thoughtExpanded ? "collapse" : "expand"})</Text>
          </Text>
          {thoughtExpanded ? (
            thoughtLines.slice(-12).map((l, i) => (
              <Text key={i} color={theme.faint} italic>
                {"  "}
                {l.slice(0, 200)}
              </Text>
            ))
          ) : (
            <Text color={theme.faint} italic>
              {"  "}
              {lastThought.slice(-160) || "…"}
            </Text>
          )}
        </Box>
      )}

      {stream ? (
        <Box flexShrink={0} flexDirection="row">
          <Box width={2} flexShrink={0}>
            <Text color={theme.orange}>✦</Text>
          </Box>
          <Box flexDirection="column" flexGrow={1}>
            <Markdown text={stream} />
          </Box>
        </Box>
      ) : null}

      {approval && (
        <Approval
          request={approval.request}
          onDecision={(ok, always) => {
            if (always) loadConfig().yolo = true;
            approval.resolve(ok);
            setApproval(null);
          }}
        />
      )}

      {effortMenu && (
        <Box flexShrink={0} flexDirection="column" borderStyle="round" borderColor={theme.orange} paddingX={1}>
          <Text bold color={theme.orange}>
            effort level <Text color={theme.faint}>(↑/↓ · enter · esc)</Text>
          </Text>
          {EFFORT_OPTIONS.map((o, i) => (
            <Text key={o.value}>
              <Text color={i === effortMenuIdx ? theme.orange : theme.faint}>
                {i === effortMenuIdx ? " ❯ " : "   "}
              </Text>
              <Text bold={i === effortMenuIdx} color={i === effortMenuIdx ? theme.ink : theme.dim}>
                {o.value.padEnd(10)}
              </Text>
              <Text color={theme.faint}> {o.blurb}</Text>
              {o.value === cfg.effort ? <Text color={theme.green}> ← current</Text> : null}
            </Text>
          ))}
        </Box>
      )}

      {todos.length > 0 && (
        <Box flexShrink={0} flexDirection="column" marginLeft={1}>
          {todos.map((t, i) => (
            <Text key={i}>
              {t.status === "done" ? (
                <Text color={theme.orange}>● </Text>
              ) : t.status === "in_progress" ? (
                <Text color={theme.ink}>◐ </Text>
              ) : (
                <Text color={theme.faint}>○ </Text>
              )}
              <Text
                bold={t.status === "in_progress"}
                color={t.status === "in_progress" ? theme.ink : t.status === "done" ? theme.dim : theme.faint}
                strikethrough={t.status === "done"}
              >
                {t.text}
              </Text>
            </Text>
          ))}
        </Box>
      )}

      {running && (
        <Box flexShrink={0}>
          <Text color={theme.orange}>{SPINNER_FRAMES[spin % SPINNER_FRAMES.length]} </Text>
          <Text color={theme.amber}>
            {activeTool
              ? `${activeTool.tool}${activeTool.hint ? ` ${activeTool.hint}` : ""}`
              : `${verbRef.current}…`}
          </Text>
          <Text color={tpsTrend === "up" ? theme.green : theme.red}>
            {"  "}
            {tpsLabel}
          </Text>
          <Text color={theme.faint}>
            {" "}· {elapsed}s · esc to interrupt
          </Text>
        </Box>
      )}

      {/* Goal indicator */}
      {goal && (
        <Box flexShrink={0} marginLeft={1}>
          <Text color={theme.orange}>✦ goal{goalRetries > 0 ? ` (attempt ${goalRetries})` : ""}: </Text>
          <Text color={theme.dim} italic>{goal.slice(0, 120)}</Text>
        </Box>
      )}

      {/* Scroll indicator — shown only while reviewing history. */}
      {clampedOffset > 0 && (
        <Box flexShrink={0} marginLeft={1}>
          <Text color={theme.amber}>⌃ scrolled up · </Text>
          <Text color={theme.faint}>PgDn (or ctrl+f) to return to the latest</Text>
        </Box>
      )}

      {/* Footer: input bar + status, welded to the bottom of the screen. Never
          unmounted, so the layout cannot snap when turns start or finish. While
          a turn runs it stays live and queues whatever you type. */}
      <Box flexShrink={0} flexDirection="column">
        <Box borderStyle="round" borderColor={running ? "#3A3A3C" : theme.faint} paddingX={1}>
          <Input
            onSubmit={submit}
            onChange={onInputChange}
            history={history}
            active={!approval && !effortMenu}
            suggestionsCount={suggestions.length}
            onSuggestionMove={(d) =>
              setSuggestionIdx((i) => (i + d + suggestions.length) % suggestions.length)
            }
            onSuggestionComplete={() => {
              const s = suggestions[suggestionIdx];
              if (!s) return null;
              const completed = `/${s.name} `;
              onInputChange(completed);
              return completed;
            }}
            onSuggestionAccept={() => {
              const s = suggestions[suggestionIdx];
              if (!s) return null;
              setSuggestions([]);
              return `/${s.name}`;
            }}
          />
        </Box>
        {suggestions.length > 0 && !running && (
          <Box flexDirection="column" marginLeft={2}>
            {suggestions.map((s, i) => (
              <Text key={s.name}>
                <Text color={i === suggestionIdx ? theme.orange : theme.faint}>
                  {i === suggestionIdx ? "❯ " : "  "}
                </Text>
                <Text bold={i === suggestionIdx} color={i === suggestionIdx ? theme.orange : theme.dim}>
                  /{s.name}
                </Text>
                <Text color={theme.faint}> — {s.description}</Text>
              </Text>
            ))}
          </Box>
        )}
        <Box marginLeft={1}>
          <Text color={theme.faint}>
            {ctrlCArmed
              ? "press ctrl+c again to quit"
              : `${effectiveModels().agent.replace("groq/", "")}${cfg.modelMode !== "default" ? ` (${cfg.modelMode})` : ""} · effort ${cfg.effort} · ctx ${fmtTok(ctxTokens)} · ${fmtTok(usage.total)} tok · ${formatCost(cost)} · ${cfg.yolo ? "yolo" : "safe"}${cfg.auto ? "+auto" : ""} · diag ${cfg.diagnostics ? "on" : "off"} · /help`}
          </Text>
        </Box>
      </Box>
    </Box>
  );
}

function ItemView({ item }: { item: Item }): React.ReactElement {
  return (
    <Box flexDirection="column" flexShrink={0} marginBottom={item.kind === "tool" ? 0 : 1}>
      {item.kind === "banner" && <Banner />}
      {item.kind === "user" && (
        <Text>
          <Text color={theme.orange} bold>
            ❯{" "}
          </Text>
          <Text color={theme.dim}>{item.text}</Text>
        </Text>
      )}
      {item.kind === "assistant" && (
        <Box flexDirection="row">
          <Box width={2} flexShrink={0}>
            <Text color={theme.orange}>✦</Text>
          </Box>
          <Box flexDirection="column" flexGrow={1}>
            <Markdown text={item.text} />
          </Box>
        </Box>
      )}
      {item.kind === "tool" && (
        <Box flexDirection="column">
          <Text>
            <Text color={item.status === "ok" ? theme.green : theme.red}>
              {item.status === "ok" ? "  ⏺" : "  ⊘"}
            </Text>
            <Text color={theme.ink}> {item.tool}</Text>
            {item.hint ? <Text color={theme.dim}> {item.hint}</Text> : null}
          </Text>
          {item.text ? (
            <Box marginLeft={4} flexDirection="column">
              {item.text.split("\n").map((l, i) => (
                <Text key={i} color={theme.faint}>
                  {l}
                </Text>
              ))}
            </Box>
          ) : null}
        </Box>
      )}
      {item.kind === "notice" && (
        <Text color={theme.dim} italic>
          ◦ {item.text}
        </Text>
      )}
      {item.kind === "error" && <Text color={theme.red}>✗ {item.text}</Text>}
      {item.kind === "shell" && (
        <Box flexDirection="column" marginLeft={2}>
          {item.text.split("\n").slice(0, 20).map((l, i) => (
            <Text key={i} color={item.status === "error" ? theme.red : theme.faint}>
              {l}
            </Text>
          ))}
        </Box>
      )}
    </Box>
  );
}

function Banner(): React.ReactElement {
  return (
    <Box flexDirection="column" marginTop={1}>
      <Text>
        <Text color={theme.orange} bold>
          ✦ glint
        </Text>
        <Text color={theme.dim}> v{VERSION} · Glint Research · a tiny agent that punches above its weight</Text>
      </Text>
      <Text color={theme.faint}>
        {"  "}groq/compound · session {SESSION_ID} · {process.cwd()}
      </Text>
      <Text color={theme.faint}>
        {"  "}/help for commands · ! for shell · traces stay local (opt out: /no-diagnostics)
      </Text>
    </Box>
  );
}

export async function startApp(opts: { yolo: boolean; intro: boolean; resume?: string }): Promise<void> {
  // Enter the alternate screen buffer so the UI owns a fixed viewport: the
  // input + status bar stay welded to the bottom and output can't scroll the
  // app off the top of the terminal. Restored on exit.
  process.stdout.write("\x1b[?1049h\x1b[2J\x1b[H");
  const instance = render(<App opts={opts} />, { exitOnCtrlC: false });
  try {
    await instance.waitUntilExit();
  } finally {
    process.stdout.write("\x1b[?1006l\x1b[?1000l");
    process.stdout.write("\x1b[?1049l");
  }
}

